def color_func(Y, mode='polygon', global_bounds=None):
    if mode == 'polygon':
        index, cmap = 0, plt.cm.Reds
    elif mode == 'center':
        index, cmap = 1, plt.cm.Blues
    else:
        return None
    low, high = global_bounds[index] if global_bounds else (Y[:, index].min(), Y[:, index].max())
    return cmap((Y[:, index] - low) / max(high - low, 1e-8))
